package dev.mesbase.platform.management;
import java.util.*;import dev.mesbase.platform.codegen.CodegenCli;
import dev.mesbase.infrastructure.persistence.*;import dev.mesbase.infrastructure.platform.*;
/** Local privileged tool. Uses environment credentials and bootstrap password; never CLI password arguments. */
public final class PlatformAdminCli {
 public static void main(String[] args){try{String username=null;boolean migrate=false;for(String arg:args){if(arg.startsWith("--username="))username=arg.substring(11);else if(arg.equals("--migrate"))migrate=true;else throw new IllegalArgumentException("Unknown argument");}if(username==null)throw new IllegalArgumentException("Username required");var app=new org.springframework.boot.SpringApplication(CodegenCli.ToolConfiguration.class);app.setWebApplicationType(org.springframework.boot.WebApplicationType.NONE);app.setBannerMode(org.springframework.boot.Banner.Mode.OFF);app.setLogStartupInfo(false);
  try(var context=app.run("--logging.level.root=ERROR")){var env=context.getEnvironment();var cfg=new com.zaxxer.hikari.HikariConfig();cfg.setJdbcUrl(env.getRequiredProperty("mes.platform.url"));cfg.setUsername(env.getRequiredProperty("mes.platform.username"));cfg.setPassword(env.getRequiredProperty("mes.platform.password"));cfg.setMaximumPoolSize(1);cfg.setMinimumIdle(0);cfg.setConnectionTimeout(5000);try(var pool=new com.zaxxer.hikari.HikariDataSource(cfg)){if(migrate)org.flywaydb.core.Flyway.configure().dataSource(pool).locations("classpath:db/platform").load().migrate();var store=new PlatformStore(new PlatformPersistence(pool,Set.of(PlatformMapper.class)));var bootstrap=new PlatformBootstrap(store,org.springframework.security.crypto.factory.PasswordEncoderFactories.createDelegatingPasswordEncoder());String id=bootstrap.provision(username,env.getRequiredProperty("MES_BOOTSTRAP_PASSWORD"));System.out.println("{\"status\":\"SUCCEEDED\",\"userId\":\""+id+"\"}");}}
 }catch(RuntimeException e){System.err.println("{\"status\":\"FAILED\",\"errorCode\":\"PROVISIONING_FAILED\"}");System.exit(2);}}
}
